action.command:
cd /workspace; cat > /tmp/flow.php <<'PHP'
<?php
require '/var/www/html/vendor/autoload.php';
require '/var/www/html/config/web.config.php';
require '/var/www/html/config/web.config.local.php';
Dsl\App\Page::$config = array_replace_recursive($config, $configLocal);
use Dsl\App\Entities\GesamtPlan;
use Dsl\App\Entities\FachPlanung;

echo "Predecessor of 2025: " . (GesamtPlan::getVorherigerGesamtPlan(GesamtPlan::getGesamtPlan(2025) ?? new stdClass) ?? 'n/a') . "\n";
$db = Dsl\App\Page::db();
$db->beginTransaction();
$r = GesamtPlan::createGesamtplan(2025, 1);
echo "createGesamtplan(2025,1) = $r\n";
if ($r === 'OK') {
    $plan = GesamtPlan::getGesamtPlan(2025);
    $f = FachPlanung::addFachPlanung('0201', $plan);
    echo "addFachPlanung(0201,2025) = " . strip_tags($f) . "\n";
    echo "massnahme copied = " . $db->querySingleRow("SELECT COUNT(*) c FROM massnahme WHERE fk_gesamtplan=2025")['c'] . "\n";
}
$db->rollBack();
echo "rolled back\n";
PHP
docker cp /tmp/flow.php ddev-tfm-fachplanung-web:/tmp/flow.php
docker exec ddev-tfm-fachplanung-web bash -c 'cd /var/www/html && php -dxdebug.mode=off /tmp/flow.php' 2>&1 | tail -12

